const LabelInput  = ({ title,  keyfld, updObs, frmNm }) => {
	const [edit, set_edit] = useState(false);
	const [obs, set_obs] = useState(1);

	
	
	const updFrm = (f, v) => {
		let frm2 = getStore(frmNm) || {};
		frm2[f] = v;
		updStore(frmNm, frm2);
		set_obs(gen16CodeId())
	};

	const success = () => {
		updObs && updObs();
		set_edit(false)
	}

	let label = getStore(frmNm)?.[keyfld];

	return (
		<div className=" dtls minhh">
			<div className="lbl_h_dtls" style={{marginTop:8, textAlign: "left"}}>
				{title}
			</div>
			{edit?
				<div className="_dsplFlx">
					<div className="lbl_dtls">
						<TextInput  
							init={label}
							width={"430px"} 
							updChanges={(e)=>updFrm(keyfld,e)}
							onEnter={success}
						/>	
					</div>
					<div className="icon_image " onClick={success}>
						<Svg name={"success"} color={"var(--success)"}/>
					</div>
				</div>
			:
			<div className="lbl_dtls"  style={{marginTop:8, textAlign: "left"}} onClick={()=>set_edit(true)}>
			{label || "click to type" }
			</div>
			}
		</div>
	)
}






const PickLabelInput  = ({ title,  keyfld, replace, frmNm, newValue, confirm, join }) => {
	const [obs, set_obs] = useState(1);

	
	
	const updFrm = (f, v) => {
		let frm2 = getStore(frmNm) || {};
		if(v){
			frm2[f] = v;
		}else{
			frm2[f] = txtOrempty(frm2[f]) +join+ newValue;
		}
		updStore(frmNm, frm2);
		set_obs(gen16CodeId())
	};

	const edit = () => {
		let vv = replace ? newValue : null;
		updFrm(keyfld, vv);
		if(isValidFunction(confirm)){
			confirm();
		}
	}

	let label = getStore(frmNm)?.[keyfld];

	return (
		<div className=" dtls minhh" onClick={()=>edit()}>
			<div className="lbl_h_dtls" style={{marginTop:8, textAlign: "left"}} >
				{title}
			</div>
			
			<div className="lbl_dtls"  style={{marginTop:8, textAlign: "left"}} >
			{label || "click to type" }
			</div>
			
		</div>
	)
}












const SVG_img  = ({ image, updTxt }) => {


	let dmz = getStore("preview_mov_dmz");
	
	
	return (
		<svg 
		
			id={"ssg_business_card_front"}  
			xmlns="http://www.w3.org/2000/svg" 
			width="100%" height="100%" 
			viewBox={`0 0 ${dmz?.w} ${dmz?.h}`} 
			preserveAspectRatio="xMidYMid meet"
			
		>
			<style type="text/css">
			{`@font-face {
				font-family: "Google Sans";
				src: url(http://fonts.gstatic.com/s/googlesans/v14/4UabrENHsxJlGDuGo1OIlLU94YtzCwY.woff2)

			}`}
			</style>
			<rect width={dmz?.w} height={dmz?.h} fill="#ffffff"></rect>
			<image width={dmz?.w} height={dmz?.h} x={0} y={0} xmlnsXlink="http://www.w3.org/1999/xlink" xlinkHref={image}></image> 
			{getStore("image_mov_text")?.map((ta, indta)=> <SvgTextAnnotationItem key={indta + "_tann" } idKey={indta + "_tann" } item={ta} index={indta} updTxt={updTxt}/>)}
			
		</svg>
	)
	
}








const SvgTextAnnotationItem  = ({ item, index, idKey, updTxt }) => {
	
	const {description, boundingPoly} = item;

	let vert = boundingPoly?.vertices;
	

	let hh =  vert?.[3]?.y - vert?.[0]?.y;
	let ww =  vert?.[1]?.x - vert?.[0]?.x ;


	const handleVisible = (e) =>{
		e.stopPropagation();
		e.preventDefault();
		updTxt(description);
		copyToClipboard(description, 1);
	}

	const handleCm = (e) =>{
		e.stopPropagation();
		e.preventDefault();
	}

	if(index === 0 || !vert?.[1]){
		return null;
	}

	
	
	

	return (
		<rect
			onClick={handleVisible}
			onContextMenu={handleCm}
			width={ww} 
			height={hh}
			fill={"#646cff"}
			fillOpacity="50%"
			x={vert?.[0]?.x }
			y={vert?.[0]?.y} 
		/>
	)

}





